/* Plan 174 (D349): typed TimeoutError throw — assigned to
* _nova_throw_scope_timeout_fn in main(). Replaces the string-fallback in
* nova_throw_scope_timeout when TimeoutError is referenced. */
static void _nova_throw_scope_timeout_impl(int64_t deadline_ns) {
Nova_TimeoutError* _e = (Nova_TimeoutError*)nova_alloc(sizeof(Nova_TimeoutError));
_e->deadline_ns = (int64_t)deadline_ns;
(void)nova_throw_typed(nova_str_from_cstr("supervised-timeout: scope deadline exceeded"), (void*)_e, NOVA_TID_USER_TimeoutError);
/* unreachable */
}

/* Plan 173.2: Supervisor decision bridge — assigned to
* _nova_supervisor_decide_fn in main(). Called by the runtime's serialized
* decision pass (nova_supervised_process_decisions, fibers.h) once per
* retained child failure, on the scope's drive thread. Maps the ambient
* Nova `Supervisor.on_child_fail(idx, err)` handler's Decision to the
* NOVA_SUPERVISE_* codes. No handler → Escalate (the default policy). */
static nova_int _nova_supervisor_decide_impl(void* _scope_v, nova_int _idx, const void* _err_v) {
NovaFiberQueue* _scope = (NovaFiberQueue*)_scope_v;
const NovaChildError* _err = (const NovaChildError*)_err_v;
NovaVtable_Supervisor* _h = _nova_handler_Supervisor;
if (!_h) return (nova_int)NOVA_SUPERVISE_ESCALATE;
/* Box the failure into Nova `any`: typed-throw payload keeps its type
* (narrowable via `err is T`); string throws / panics box the message
* as `str`. */
void* _e_any = NULL;
if (_err->payload != NULL && _err->tid != 0) {
_e_any = nova_any_from_boxed(_err->payload, _err->tid);
} else {
nova_str _m = nova_str_from_cstr(_err->msg ? _err->msg : "");
_e_any = nova_any_box(&NOVA_TYPEINFO_nova_str, &_m, sizeof(nova_str));
}
/* Q-block (173.2): `Fail` is allowed inside the handler = Escalate-with-
* handler-error. Guard the invocation with a local fail-frame so a
* handler throw cannot longjmp past the drive loop (which would abandon
* still-running children); the thrown error is fed into the scope's
* primary machinery and the child failure escalates normally (rank
* precedence decides the surviving primary — a child PANIC still wins,
* D13). */
NovaFailFrame _sf;
nova_fail_push(&_sf);
if (setjmp(_sf.jmp) == 0) {
/* 173.4 Ph.2(v): child's pocket around the arm — see fibers.h. */
NovaErrorChain* _sv_pocket = _nova_last_error.frame.error_suppressed;
_nova_last_error.frame.error_suppressed = _err->suppressed;
Nova_Decision* _d = _h->on_child_fail(_h->ctx, _idx, _e_any);
_nova_last_error.frame.error_suppressed = _sv_pocket;
nova_fail_pop();
if (_d == NULL) return (nova_int)NOVA_SUPERVISE_ESCALATE;
switch (_d->tag) {
case NOVA_TAG_Decision_Stop:     return (nova_int)NOVA_SUPERVISE_STOP;
/* Escalate + defensive default: словарь Decision = Escalate|Stop
* (Restart-семейство ретрактировано, D416-амендмент 2026-07-10). */
case NOVA_TAG_Decision_Escalate:
default:                         return (nova_int)NOVA_SUPERVISE_ESCALATE;
}
} else {
nova_fail_pop();
nova_fiber_report_atomic_kinded(_scope, _sf.error_msg.ptr, _sf.error_kind,
_sf.error_reason_ptr, _sf.error_user_payload,
_sf.error_user_type_id);
return (nova_int)NOVA_SUPERVISE_ESCALATE;
}
}

